-- SpecialMesh.MeshId per kit mesh. The kit meshes are built to fit a 2-stud box; if an upload comes in at a
-- different size, set MESH_SCALE[name] so Scale 1 = that 2-stud box.
local MESHES = {
	claw_cluster = "rbxassetid://0", -- assets/meshes/claw_cluster.fbx
	cone_tube = "rbxassetid://0", -- assets/meshes/cone_tube.fbx
	crescent_thin = "rbxassetid://0", -- assets/meshes/crescent_thin.fbx
	crescent_wide = "rbxassetid://0", -- assets/meshes/crescent_wide.fbx
	dome = "rbxassetid://0", -- assets/meshes/dome.fbx
	dragon_head = "rbxassetid://0", -- assets/meshes/dragon_head.fbx
	giant_fist = "rbxassetid://0", -- assets/meshes/giant_fist.fbx
	phoenix_bird = "rbxassetid://0", -- assets/meshes/phoenix_bird.fbx
	sphere = "rbxassetid://0", -- assets/meshes/sphere.fbx
	spike = "rbxassetid://0", -- assets/meshes/spike.fbx
	spike_bent = "rbxassetid://0", -- assets/meshes/spike_bent.fbx
	spike_cluster = "rbxassetid://0", -- assets/meshes/spike_cluster.fbx
	swirl = "rbxassetid://0", -- assets/meshes/swirl.fbx
	swirl_tight = "rbxassetid://0", -- assets/meshes/swirl_tight.fbx
	tube = "rbxassetid://0", -- assets/meshes/tube.fbx
	wave_curl = "rbxassetid://0", -- assets/meshes/wave_curl.fbx
}

local MESH_SCALE = {}

local Assets = {}

function Assets.texture(name)
	local id = TEXTURES[name]
	if id and id ~= "rbxassetid://0" then
		return id
	end
	return FALLBACK_TEXTURE
end

function Assets.mesh(name)
	local id = MESHES[name]
	return (id and id ~= "rbxassetid://0") and id or ""
end

function Assets.meshScale(name)
	return MESH_SCALE[name] or 1
end

Assets.TEXTURES = TEXTURES
Assets.MESHES = MESHES
return Assets
